alpha-algorithm.pseudocode:
def footprint(log):  # log: 트레이스(활동 문자열) 목록
    acts = {a for t in log for a in t}
    follows = {(t[i], t[i + 1]) for t in log
               for i in range(len(t) - 1)}  # 직접 후행 >
    rel = {}
    for a in acts:
        for b in acts:
            ab = (a, b) in follows
            ba = (b, a) in follows
            if ab and not ba:
                rel[a, b] = '→'  # 인과
            elif ba and not ab:
                rel[a, b] = '←'
            elif ab and ba:
                rel[a, b] = '‖'  # 병렬
            else:
                rel[a, b] = '#'  # 무관 (선택 관계)
    starts = {t[0] for t in log}  # 시작 활동 TI
    ends = {t[-1] for t in log}  # 종료 활동 TO
    return rel, starts, ends
