alpha-beta-pruning.pseudocode:
INF = float('inf')

def alphabeta(node, depth, a, b, is_max):
    # a(α): MAX가 보장한 하한, b(β): MIN이 보장한 상한
    if depth == 0 or node.is_terminal():
        return evaluate(node)
    if is_max:
        value = -INF
        for child in node.children():
            v = alphabeta(child, depth - 1, a, b, False)
            value = max(value, v)
            a = max(a, value)
            if a >= b:
                break  # β 절단: MIN이 이 분기를 택하지 않음
        return value
    value = INF
    for child in node.children():
        v = alphabeta(child, depth - 1, a, b, True)
        value = min(value, v)
        b = min(b, value)
        if a >= b:
            break  # α 절단: MAX가 이 분기를 택하지 않음
    return value

alpha-blending.pseudocode:
def render(opaque, transparent, fb, eye):
    for obj in opaque:  # 1) 불투명 먼저 (깊이 쓰기)
        draw(obj, fb)
    # 2) 반투명은 시점에서 먼 것부터 (뒤 → 앞)
    far_first = sorted(transparent,
                       key=lambda o: -distance(o, eye))
    for obj in far_first:
        for x, y, src, a in fragments(obj):
            dst = fb[y][x]
            # over 연산: C = αCsrc + (1 − α)Cdst
            fb[y][x] = a * src + (1 - a) * dst
